fn start_campaign_agent_run(
    &mut self,
    request: &CampaignRunRequest,
) -> Result<String, String> {
    let proposal = campaign_agent_proposal(request)?;
    let session_id = self
        .host
        .create_session(format!("ADR 0156 {}", request.schedule.task_id))
        .map_err(|error| error.to_string())?;
    self.selected_session = session_id.clone();
    self.host
        .append_message(
            &session_id,
            ConversationRole::User,
            request.candidate_contract.prompt.clone(),
        )
        .map_err(|error| error.to_string())?;
    let version = self
        .host
        .update_proposal(&session_id, proposal.clone())
        .map_err(|error| error.to_string())?;
    self.proposal_draft = proposal;
    self.proposal_draft.version = version;

    let config = NativeModelConfig::Local(LocalModelConfig {
        endpoint: self.local_model_endpoint.clone(),
        model: request.model.model_id.clone(),
    });
    let run_id = self
        .host
        .start_run_authorized(&session_id, version, config.label())
        .map_err(|error| error.to_string())?;
    self.active_run_id = Some(run_id.clone());
    self.active_runtime_mode = Some(AgentRuntimeMode::Native);
    self.active_external_provider = None;
    self.active_external_program = None;
    self.active_external_args = None;
    self.external_provider_diagnostics = ExternalAgentDiagnostics::default();
    self.native_agent_runtime = Some(NativeAgentRuntime::configured(config.clone()));
    let inventory = self.current_installed_inventory().cloned();
    self.native_run_benchmark_context = Some(NativeRunBenchmarkContext {
        run_id: run_id.clone(),
        task_id: request.schedule.task_id.clone(),
        backend_id: config.backend_id().to_owned(),
        model_id: config.model_id(),
        quality: self.quality_preference,
        workload: campaign_task_workload(&request.schedule.task_id)?,
        hardware: self.benchmark_hardware.clone(),
        inventory,
        routed: false,
    });
    self.native_mcp_task = None;
    self.pending_native_mcp_tool = None;
    self.code_workspace = None;
    self.pending_code_changes.clear();
    self.pending_permission = None;
    self.pending_runtime_action = None;
    self.managed_input_recipe.clear();
    self.managed_candidate_input_recipe.clear();
    self.managed_runtime_plan_completed = false;
    self.managed_runtime_debug_observation = None;
    self.managed_playtest_requested = false;
    self.managed_capture_requested = false;
    self.managed_repair_requested = false;
    self.managed_runtime_repairs = 0;
    self.managed_runtime_observation = None;
    self.managed_evaluation_requested = false;
    self.native_evaluation_had_image = false;
    self.managed_playtest_started_at = None;
    self.last_captured_frame = None;

    let task = benchmark_task(&request.schedule.task_id)
        .ok_or_else(|| "frozen benchmark task descriptor is unavailable".to_owned())?;
    if task.kind == BenchmarkTaskKind::ValidationRepair {
        self.prepare_native_workspace(&run_id)?;
        self.host
            .transition_run(
                &run_id,
                AgentRunState::Executing,
                "ADR 0156 validation-repair baseline entered normal execution before validation.",
            )
            .map_err(|error| error.to_string())?;
        self.host
            .begin_managed_validation(&run_id, false)
            .map_err(|error| error.to_string())?;
    } else {
        self.start_native_agent_execution(&run_id)?;
    }
    Ok(run_id)
}

fn resolve_campaign_pending_permission(&mut self) -> Result<(), String> {
    let Some(pending) = self.pending_permission.as_ref() else {
        return Ok(());
    };
    let run_id = pending.run_id.clone();
    let capability = pending.capability;
    let action = pending.action.clone();
    let allowed = self
        .host
        .run(&run_id)
        .map_err(|error| error.to_string())?
        .proposal_snapshot
        .requested_capabilities
        .contains(&capability);
    if !allowed {
        self.pending_permission = None;
        return Err(format!(
            "benchmark model requested capability `{}` outside the frozen campaign budget",
            capability.label()
        ));
    }
    self.pending_permission = None;
    self.host
        .resolve_permission(&run_id, capability, ApprovalScope::Run)
        .map_err(|error| error.to_string())?;
    self.execute_permission_action(&run_id, action);
    Ok(())
}

fn maybe_apply_campaign_code_changes(
    &mut self,
    request: &CampaignRunRequest,
) -> Result<(), String> {
    let task = benchmark_task(&request.schedule.task_id)
        .ok_or_else(|| "frozen benchmark task descriptor is unavailable".to_owned())?;
    if !matches!(
        task.kind,
        BenchmarkTaskKind::CodeImplementation | BenchmarkTaskKind::ValidationRepair
    ) || self.pending_code_changes.is_empty()
    {
        return Ok(());
    }
    let Some(run_id) = self.active_run_id.clone() else {
        return Err("benchmark code apply lost the active AgentRun".to_owned());
    };
    if !self
        .host
        .run(&run_id)
        .is_ok_and(|run| run.state == AgentRunState::Evaluating)
    {
        return Ok(());
    }
    if self.pending_permission.is_none() {
        self.request_permission(
            run_id,
            AgentCapability::CodeWorkspaceApply,
            PendingPermissionAction::ApplyCodeChanges,
        );
    }
    self.resolve_campaign_pending_permission()
}

fn request_code_apply(&mut self) {
    let Some(run_id) = self.active_run_id.clone() else {
        return;
    };
